<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue'; import { HostSurface } from '../../platform/host-adapter.mjs'; import { createEventsApi } from './domain/events-api.mjs'; import EventsListDesktop from './desktop/EventsListDesktop.vue'; import EventsListMobile from './mobile/EventsListMobile.vue';
const props = defineProps({ surface: String, adapter: Object, hostUnavailable: Boolean }); const emit = defineEmits(['back']); const api = createEventsApi(); const safeArea = ref(props.adapter?.getSafeArea?.() || {}); const isNative = computed(() => props.surface === HostSurface.NATIVE); const state = reactive({ phase: 'loading', rows: [], total: 0, page: 1, pageSize: 20, search: '', error: null }); const safeAreaStyle = computed(() => Object.fromEntries(['top','right','bottom','left'].flatMap((side) => Number.isFinite(Number(safeArea.value?.[side])) ? [[`--mds-mobile-safe-${side}`, `${Number(safeArea.value[side])}px`]] : [])));
async function load({ page = state.page, search = state.search } = {}) { if (props.hostUnavailable) { state.phase = 'error'; state.error = { status: 503, message: 'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.' }; return; } state.phase = 'loading'; try { const p = await api.getList({ page, pageSize: state.pageSize, search }); Object.assign(state, { rows: p.rows, total: p.total, page: p.page, pageSize: p.pageSize, search, phase: 'ready' }); } catch (error) { state.phase = 'error'; state.error = error; } } async function back() { if (isNative.value && props.adapter) return props.adapter.goBack({ reason: 'events-list' }); emit('back'); } onMounted(load);
</script>
<template><div v-if="state.phase === 'loading'" :class="isNative ? 'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]' : 'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'"><MSpinner :size="28" /></div><section v-else-if="state.phase === 'error'" :class="isNative ? 'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]' : 'min-h-[360px] bg-[var(--mds-bg-page)]'"><MMobileTopBar v-if="isNative" title="Sự kiện" @back="back" /><MEmptyState :title="state.error.status === 403 ? 'Bạn không có quyền xem sự kiện' : 'Không thể mở sự kiện'" :description="state.error.message" /></section><EventsListMobile v-else-if="isNative" :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :safe-area-style="safeAreaStyle" @back="back" @search="load({ page: 1, search: $event })" @page="load({ page: $event })" /><EventsListDesktop v-else :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" @search="load({ page: 1, search: $event })" @page="load({ page: $event })" /></template>
